describe('Session Expiration After Inactivity', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should expire session after 30 minutes of inactivity', () => {
    // Login successfully
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('Password123!');
    cy.get('[data-testid="login-button"]').click();

    // Verify successful login
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');

    // Wait for 30 minutes of inactivity
    cy.clock();
    cy.wait(30 * 60 * 1000);
    cy.tick(30 * 60 * 1000);

    // Verify session has expired and user is redirected to login
    cy.url().should('include', '/login');
    cy.get('[data-testid="welcome-message"]').should('not.exist');
    cy.get('[data-testid="session-expired-message"]').should('be.visible');
  });

  it('should not expire session when user is active', () => {
    // Login successfully
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('Password123!');
    cy.get('[data-testid="login-button"]').click();

    // Verify successful login
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');

    // Perform an action to keep session alive
    cy.get('[data-testid="dashboard-button"]').click();
    cy.get('[data-testid="profile-link"]').click();

    // Wait for 30 minutes of inactivity
    cy.clock();
    cy.wait(30 * 60 * 1000);
    cy.tick(30 * 60 * 1000);

    // Verify session is still active
    cy.url().should('include', '/profile');
    cy.get('[data-testid="welcome-message"]').should('be.visible');
    cy.get('[data-testid="session-expired-message"]').should('not.exist');
  });
});
